window.elysianLogout = function () {
  try { localStorage.removeItem('elysian_user_name'); } catch (e) {}
  var done = function () { location.href = '/?loggedout=' + Date.now(); };
  // Dummy credentials force the browser to drop the cached Basic Auth user.
  fetch(location.protocol + '//logout:logout@' + location.host + '/api/logout?t=' + Date.now(), { credentials: 'omit' })
    .catch(function () {})
    .finally(done);
};

