window.elysianLogout = function () {
  try { localStorage.clear(); sessionStorage.clear(); } catch (e) {}
  // Clears the httpOnly session cookie on the server and shows /login.
  // Chrome cannot forget Basic Auth; sessions are what make Log out real.
  location.replace('/api/logout?t=' + Date.now());
};
